package toolsy

import (
	"context"
	"reflect"
)

// MemoryAccess describes how a tool uses session in-memory state.
type MemoryAccess string

const (
	MemoryAccessNone      MemoryAccess = "none"
	MemoryAccessRead      MemoryAccess = "read"
	MemoryAccessReadWrite MemoryAccess = "readwrite"
)

// Permission is a host-defined capability label declared on a tool manifest.
type Permission string

// ToolRequirements holds typed declarative requirements for authorization and routing.
// Registry/session policy can enforce these requirements before execution with [NewRequirementsPolicy].
type ToolRequirements struct {
	MemoryAccess MemoryAccess
	NeedsSession bool
	Permissions  []Permission
}

// RequirementsPolicyRequest is the typed request passed to requirements policy.
type RequirementsPolicyRequest[TSubject, TScope any] struct {
	Manifest     ToolManifest
	Requirements ToolRequirements
	Input        ToolInput
	Context      TypedCallContext[TSubject, TScope]
	View         RegistryViewSnapshot
}

// RequirementsDecisionFunc evaluates manifest requirements against a typed subject/scope.
type RequirementsDecisionFunc[TSubject, TScope any] func(
	context.Context,
	RequirementsPolicyRequest[TSubject, TScope],
) Decision

// NewRequirementsPolicy converts manifest requirements into fail-closed registry/session enforcement.
func NewRequirementsPolicy[TSubject, TScope any](
	fn RequirementsDecisionFunc[TSubject, TScope],
) Policy {
	return requirementsPolicy[TSubject, TScope]{fn: fn}
}

type requirementsPolicy[TSubject, TScope any] struct {
	fn RequirementsDecisionFunc[TSubject, TScope]
}

func (p requirementsPolicy[TSubject, TScope]) Decide(ctx context.Context, req PolicyRequest) Decision {
	if p.fn == nil {
		return DenyDecision("requirements policy function is nil")
	}
	if !hasRequirements(req.Manifest.Requirements) {
		return AllowDecision()
	}
	typed, err := TypedContext[TSubject, TScope](req.CallContext)
	if err != nil {
		return DenyDecision(err.Error())
	}
	return p.fn(ctx, RequirementsPolicyRequest[TSubject, TScope]{
		Manifest:     cloneManifestForPolicy(req.Manifest),
		Requirements: cloneRequirements(req.Manifest.Requirements),
		Input:        req.Input.Clone(),
		Context:      typed,
		View:         cloneRegistryViewSnapshot(req.View),
	})
}

func (p requirementsPolicy[TSubject, TScope]) enforcesRequirements() bool {
	return true
}

func hasRequirements(r ToolRequirements) bool {
	return r.NeedsSession ||
		(r.MemoryAccess != "" && r.MemoryAccess != MemoryAccessNone) ||
		len(r.Permissions) > 0
}

// cloneRequirements returns a defensive copy of requirements.
func cloneRequirements(r ToolRequirements) ToolRequirements {
	out := r
	if r.Permissions != nil {
		out.Permissions = make([]Permission, len(r.Permissions))
		copy(out.Permissions, r.Permissions)
	}
	return out
}

func cloneManifestForPolicy(m ToolManifest) ToolManifest {
	out := m
	out.Parameters = deepCloneMap(m.Parameters)
	out.OutputSchema = deepCloneMap(m.OutputSchema)
	out.Tags = append([]string(nil), m.Tags...)
	out.Requirements = cloneRequirements(m.Requirements)
	return out
}

func deepCloneMap(in map[string]any) map[string]any {
	if len(in) == 0 {
		return nil
	}
	out, ok := cloneMutableValue(in).(map[string]any)
	if !ok {
		return nil
	}
	return out
}

func deepCloneValue(v any) any {
	return cloneMutableValue(v)
}

func cloneMutableValue(v any) any {
	if v == nil {
		return v
	}
	cloned := cloneReflectValue(reflect.ValueOf(v))
	if !cloned.IsValid() || !cloned.CanInterface() {
		return v
	}
	return cloned.Interface()
}

func cloneReflectValue(v reflect.Value) reflect.Value {
	c := valueCloner{} //nolint:exhaustruct_v5 // Each operation starts with an empty memo.
	defer c.release()
	return c.clone(v)
}

type cloneReference struct {
	typeOf  reflect.Type
	pointer uintptr
	length  int
}

type valueCloner struct {
	memo *cloneMemo
}

// Exported data fields are snapshotted without JSON type erasure. Opaque private
// state, functions and channels remain host-owned and must be immutable during
// execution. Cycles are preserved rather than recursed indefinitely.
func (c *valueCloner) clone(v reflect.Value) reflect.Value {
	if !v.IsValid() {
		return v
	}
	switch v.Kind() {
	case reflect.Interface:
		if v.IsNil() {
			return reflect.Zero(v.Type())
		}
		out := reflect.New(v.Type()).Elem()
		out.Set(c.clone(v.Elem()))
		return out
	case reflect.Pointer, reflect.Map, reflect.Slice:
		return c.cloneReference(v)
	case reflect.Array:
		out := reflect.New(v.Type()).Elem()
		for i := range v.Len() {
			out.Index(i).Set(c.clone(v.Index(i)))
		}
		return out
	case reflect.Struct:
		out := reflect.New(v.Type()).Elem()
		out.Set(v)
		for i := range v.NumField() {
			if v.Type().Field(i).IsExported() {
				out.Field(i).Set(c.clone(v.Field(i)))
			}
		}
		return out
	case reflect.Invalid,
		reflect.Bool,
		reflect.Int,
		reflect.Int8,
		reflect.Int16,
		reflect.Int32,
		reflect.Int64,
		reflect.Uint,
		reflect.Uint8,
		reflect.Uint16,
		reflect.Uint32,
		reflect.Uint64,
		reflect.Uintptr,
		reflect.Float32,
		reflect.Float64,
		reflect.Complex64,
		reflect.Complex128,
		reflect.Chan,
		reflect.Func,
		reflect.String,
		reflect.UnsafePointer:
		return v
	default:
		return v
	}
}

func (c *valueCloner) cloneReference(v reflect.Value) reflect.Value {
	if v.IsNil() {
		return reflect.Zero(v.Type())
	}
	key := cloneReference{typeOf: v.Type(), pointer: uintptr(v.UnsafePointer()), length: 0}
	if v.Kind() == reflect.Slice {
		key.length = v.Len()
	}
	if out, exists := c.lookup(key); exists {
		return out
	}
	if out, ok := c.cloneJSONReference(v, key); ok {
		return out
	}
	var out reflect.Value
	switch v.Kind() {
	case reflect.Pointer:
		out = reflect.New(v.Type().Elem())
		if out.Type() != v.Type() {
			out = out.Convert(v.Type())
		}
		c.remember(key, out)
		out.Elem().Set(c.clone(v.Elem()))
	case reflect.Map:
		out = reflect.MakeMapWithSize(v.Type(), v.Len())
		c.remember(key, out)
		iter := v.MapRange()
		for iter.Next() {
			out.SetMapIndex(iter.Key(), c.clone(iter.Value()))
		}
	case reflect.Slice:
		out = reflect.MakeSlice(v.Type(), v.Len(), v.Len())
		c.remember(key, out)
		for i := range v.Len() {
			out.Index(i).Set(c.clone(v.Index(i)))
		}
	case reflect.Invalid,
		reflect.Bool,
		reflect.Int,
		reflect.Int8,
		reflect.Int16,
		reflect.Int32,
		reflect.Int64,
		reflect.Uint,
		reflect.Uint8,
		reflect.Uint16,
		reflect.Uint32,
		reflect.Uint64,
		reflect.Uintptr,
		reflect.Float32,
		reflect.Float64,
		reflect.Complex64,
		reflect.Complex128,
		reflect.Array,
		reflect.Chan,
		reflect.Func,
		reflect.Interface,
		reflect.String,
		reflect.Struct,
		reflect.UnsafePointer:
		panic("toolsy: invalid internal snapshot reference kind")
	default:
		panic("toolsy: invalid internal snapshot reference kind")
	}
	return out
}

// cloneAny shares the reference memo across exact JSON containers and BYOT data.
func (c *valueCloner) cloneAny(value any) any {
	cloned := c.clone(reflect.ValueOf(value))
	if !cloned.IsValid() {
		return nil
	}
	return cloned.Interface()
}

func (c *valueCloner) cloneJSONReference(v reflect.Value, key cloneReference) (reflect.Value, bool) {
	if !v.CanInterface() {
		return reflect.Value{}, false
	}
	if values, ok := reflect.TypeAssert[map[string]any](v); ok {
		copied := make(map[string]any, len(values))
		out := reflect.ValueOf(copied)
		c.remember(key, out)
		for name, value := range values {
			copied[name] = c.cloneAny(value)
		}
		return out, true
	}
	if values, ok := reflect.TypeAssert[[]any](v); ok {
		copied := make([]any, len(values))
		out := reflect.ValueOf(copied)
		c.remember(key, out)
		for i, value := range values {
			copied[i] = c.cloneAny(value)
		}
		return out, true
	}
	return reflect.Value{}, false
}

clone_memo.go.source:
package toolsy

import "reflect"

const (
	cloneMemoSlots   = 512
	cloneMemoEntries = 384
	cloneMemoIdle    = 4
)

type cloneMemoEntry struct {
	key   cloneReference
	value reflect.Value
}

// Fixed storage is the only scratch retained between operations. Overflow maps
// are dropped on release, so graph size cannot enlarge the idle store.
type cloneMemo struct {
	entries  [cloneMemoSlots]cloneMemoEntry
	used     [cloneMemoEntries]uint16
	count    int
	overflow map[cloneReference]reflect.Value
}

//nolint:gochecknoglobals // Process-wide idle scratch has a fixed four-instance bound.
var idleCloneMemos = make(chan *cloneMemo, cloneMemoIdle)

func (c *valueCloner) lookup(key cloneReference) (reflect.Value, bool) {
	if c.memo == nil {
		select {
		case c.memo = <-idleCloneMemos:
		default:
			c.memo = &cloneMemo{}
		}
	}
	slot := cloneMemoSlot(key)
	for {
		entry := &c.memo.entries[slot]
		if entry.key.typeOf == nil {
			break
		}
		if entry.key == key {
			return entry.value, true
		}
		slot = (slot + 1) & (cloneMemoSlots - 1)
	}
	out, ok := c.memo.overflow[key]
	return out, ok
}

//nolint:mnd // Fixed integer hash mixing constants.
func cloneMemoSlot(key cloneReference) uintptr {
	// Mix alignment bits and slice length; type is checked by full key equality.
	hash := key.pointer ^ uintptr(key.length)
	hash ^= hash >> 16
	hash *= 0x45d9f3b
	hash ^= hash >> 16
	return hash & (cloneMemoSlots - 1)
}

func (c *valueCloner) remember(key cloneReference, value reflect.Value) {
	memo := c.memo
	if memo.count == cloneMemoEntries {
		if memo.overflow == nil {
			memo.overflow = make(map[cloneReference]reflect.Value)
		}
		memo.overflow[key] = value
		return
	}
	slot := cloneMemoSlot(key)
	for memo.entries[slot].key.typeOf != nil {
		slot = (slot + 1) & (cloneMemoSlots - 1)
	}
	memo.entries[slot] = cloneMemoEntry{key: key, value: value}
	memo.used[memo.count] = uint16(slot)
	memo.count++
}

func (c *valueCloner) release() {
	if c.memo == nil {
		return
	}
	memo := c.memo
	for i, slot := range memo.used[:memo.count] {
		clear(memo.entries[slot : slot+1])
		memo.used[i] = 0
	}
	memo.count = 0
	memo.overflow = nil
	c.memo = nil
	select {
	case idleCloneMemos <- memo:
	default:
	}
}
